              color={colors.text.secondary}
              size={iconSizes.small}
              strokeWidth={2}
            />
            <Text
              style={{
                ...typography.body,
                fontWeight: fontWeights.semibold,
                color: colors.text.primary,
              }}
            >
              Advanced
            </Text>
          </View>
          <Animated.View style={chevronStyle}>
