            {growthMeta ? (
              <View
                accessibilityLabel={`Growth Type: ${growthMeta.label}`}
                className='flex-row items-center self-start rounded-full px-3 py-1.5'
                style={{
                  backgroundColor: growthMeta.pillBg,
                  marginLeft: 4,
