                <Sprout
                  color={growthMeta.pillFg}
                  size={14}
                  strokeWidth={2.5}
                />
                <Text
                  style={{
                    ...typography.caption,
                    fontSize: 12,
                    fontWeight: fontWeights.semibold,
                    color: growthMeta.pillFg,
                    marginLeft: 6,
                  }}
                >
                  Growth Type · {growthMeta.label} · ~{growthMeta.days}-day build
                </Text>
